import { useEffect, useState } from 'react';
import { CalendarClock, Pencil, Plus, Power, Save, X } from 'lucide-react';
import { vendorAPI } from '../../services/api';
import Loader from '../../components/common/Loader';
import toast from 'react-hot-toast';

const blank = { product: '', name: '', frequency: 'monthly', interval: 1, price: '', discountPercentage: 0, isActive: true };

export default function VendorSubscriptionPlansPage() {
  const [plans, setPlans] = useState([]);
  const [products, setProducts] = useState([]);
  const [form, setForm] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const load = async () => { setLoading(true); try { const [planResponse, productResponse] = await Promise.all([vendorAPI.getSubscriptionPlans(), vendorAPI.getProducts({ approvalStatus: 'approved', limit: 100 })]); setPlans(planResponse.data?.plans || []); setProducts((productResponse.data?.data || []).filter(product => product.approvalStatus === 'approved' && product.isActive !== false)); } catch (error) { toast.error(error.message || 'Could not load subscription plans'); } finally { setLoading(false); } };
  useEffect(() => { load(); }, []);
  const openNew = () => setForm({ ...blank, product: products[0]?._id || '', price: products[0]?.price || '' });
  const save = async () => { if (!form?.product || !form.name.trim()) return toast.error('Select a product and enter a plan name'); setSaving(true); try { if (form._id) await vendorAPI.updateSubscriptionPlan(form._id, form); else await vendorAPI.createSubscriptionPlan(form); toast.success('Subscription plan saved'); setForm(null); load(); } catch (error) { toast.error(error.message || 'Could not save subscription plan'); } finally { setSaving(false); } };
  const deactivate = async plan => { if (!window.confirm(`Deactivate ${plan.name}?`)) return; try { await vendorAPI.deactivateSubscriptionPlan(plan._id); toast.success('Plan deactivated'); load(); } catch (error) { toast.error(error.message || 'Could not deactivate plan'); } };
  const updateForm = (key, value) => setForm(current => ({ ...current, [key]: value }));
  if (loading) return <div className="flex justify-center py-16"><Loader /></div>;
  return <div className="mx-auto max-w-6xl space-y-6" data-testid="vendor-subscription-plans-page">
    <header className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-indigo-600">Seller catalog</p><h1 className="mt-2 text-2xl font-bold text-gray-900">Subscription plans</h1><p className="mt-1 text-sm text-gray-500">Create recurring plans for your own admin-approved products.</p></div><button type="button" data-testid="vendor-plan-new" onClick={openNew} disabled={!products.length} className="inline-flex items-center gap-2 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50"><Plus size={16} />New plan</button></header>
    {form && <section className="rounded-2xl border border-indigo-100 bg-indigo-50/50 p-5"><div className="mb-4 flex items-center justify-between"><h2 className="font-bold text-gray-900">{form._id ? 'Edit plan' : 'New plan'}</h2><button type="button" onClick={() => setForm(null)} className="rounded-lg p-1 text-gray-400 hover:bg-white" aria-label="Close"><X size={17} /></button></div><div className="grid gap-4 md:grid-cols-2"><label className="text-xs font-semibold uppercase tracking-wide text-gray-600">Product<select data-testid="vendor-plan-product" value={form.product} disabled={Boolean(form._id)} onChange={event => updateForm('product', event.target.value)} className="mt-1 w-full rounded-xl border border-gray-200 bg-white px-3 py-2.5 text-sm font-normal normal-case"><option value="">Select approved product</option>{products.map(product => <option key={product._id} value={product._id}>{product.title}</option>)}</select></label><label className="text-xs font-semibold uppercase tracking-wide text-gray-600">Plan name<input data-testid="vendor-plan-name" value={form.name} onChange={event => updateForm('name', event.target.value)} className="mt-1 w-full rounded-xl border border-gray-200 bg-white px-3 py-2.5 text-sm font-normal normal-case" placeholder="Monthly essentials" /></label><label className="text-xs font-semibold uppercase tracking-wide text-gray-600">Frequency<select value={form.frequency} onChange={event => updateForm('frequency', event.target.value)} className="mt-1 w-full rounded-xl border border-gray-200 bg-white px-3 py-2.5 text-sm font-normal normal-case"><option value="weekly">Weekly</option><option value="monthly">Monthly</option><option value="custom">Custom</option></select></label><label className="text-xs font-semibold uppercase tracking-wide text-gray-600">Interval<input type="number" min="1" max="52" value={form.interval} onChange={event => updateForm('interval', Number(event.target.value))} className="mt-1 w-full rounded-xl border border-gray-200 bg-white px-3 py-2.5 text-sm font-normal normal-case" /></label><label className="text-xs font-semibold uppercase tracking-wide text-gray-600">Price (₹)<input type="number" min="0" step="0.01" value={form.price} onChange={event => updateForm('price', event.target.value)} className="mt-1 w-full rounded-xl border border-gray-200 bg-white px-3 py-2.5 text-sm font-normal normal-case" /></label><label className="text-xs font-semibold uppercase tracking-wide text-gray-600">Discount (%)<input type="number" min="0" max="100" step="0.01" value={form.discountPercentage} onChange={event => updateForm('discountPercentage', Number(event.target.value))} className="mt-1 w-full rounded-xl border border-gray-200 bg-white px-3 py-2.5 text-sm font-normal normal-case" /></label></div><button type="button" data-testid="vendor-plan-save" onClick={save} disabled={saving} className="mt-4 inline-flex items-center gap-2 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50"><Save size={16} />{saving ? 'Saving…' : 'Save plan'}</button></section>}
    <section className="grid gap-4 md:grid-cols-2">{plans.map(plan => <article key={plan._id} className="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-wide text-indigo-500">{plan.product?.title || 'Product'}</p><h2 className="mt-1 font-bold text-gray-900">{plan.name}</h2></div><span className={`rounded-full px-2.5 py-1 text-[11px] font-semibold ${plan.isActive ? 'bg-emerald-50 text-emerald-700' : 'bg-gray-100 text-gray-500'}`}>{plan.isActive ? 'Active' : 'Inactive'}</span></div><div className="mt-5 grid grid-cols-2 gap-3 text-sm"><div><span className="block text-xs text-gray-400">Price</span><strong>{plan.price} / {plan.frequency}</strong></div><div><span className="block text-xs text-gray-400">Interval</span><strong>{plan.interval} period(s)</strong></div><div><span className="block text-xs text-gray-400">Discount</span><strong>{plan.discountPercentage || 0}%</strong></div><div><span className="block text-xs text-gray-400">Created</span><strong>{new Date(plan.createdAt).toLocaleDateString()}</strong></div></div><div className="mt-5 flex gap-2 border-t border-gray-100 pt-4"><button type="button" onClick={() => setForm({ ...blank, ...plan, product: plan.product?._id || plan.product, price: plan.price })} className="inline-flex items-center gap-2 rounded-xl bg-indigo-50 px-3 py-2 text-sm font-semibold text-indigo-700"><Pencil size={14} />Edit</button>{plan.isActive && <button type="button" onClick={() => deactivate(plan)} className="inline-flex items-center gap-2 rounded-xl bg-rose-50 px-3 py-2 text-sm font-semibold text-rose-700"><Power size={14} />Deactivate</button>}</div></article>)}{!plans.length && <div className="rounded-2xl border border-dashed border-gray-300 p-12 text-center text-sm text-gray-400 md:col-span-2"><CalendarClock className="mx-auto mb-3 text-gray-300" size={32} />No subscription plans yet. Create one for an approved product.</div>}</section>
  </div>;
}
